import{_ as a,o,c as t,a5 as r}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"3.4.11 View Workspace Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-11-view-workspace-dashboard/spec.md","filePath":"feature/agency-workspace/3-4-11-view-workspace-dashboard/spec.md"}'),s={name:"feature/agency-workspace/3-4-11-view-workspace-dashboard/spec.md"};function i(n,e,c,d,l,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="_3-4-11-view-workspace-dashboard" tabindex="-1">3.4.11 View Workspace Dashboard <a class="header-anchor" href="#_3-4-11-view-workspace-dashboard" aria-label="Permalink to &quot;3.4.11 View Workspace Dashboard&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.4.11</td></tr><tr><td>Feature</td><td>View Workspace Dashboard</td></tr><tr><td>Domain</td><td>Agency &amp; Workspace (FR 3.4)</td></tr><tr><td>Role</td><td>MANAGER / CREATOR / CLIENT</td></tr><tr><td>Version</td><td>2.3 — 2026-09-25 — implemented; rewritten to match real <code>WorkspaceServiceImpl.getDashboard</code></td></tr><tr><td>Document status</td><td>Implemented</td></tr></tbody></table><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>Begins when a Workspace member opens the Dashboard of a Workspace (<code>/workspaces/:id/dashboard</code>).</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> Workspace members with role MANAGER, CREATOR, or CLIENT.</li><li><strong>Purpose:</strong> Gives members an overview of the Workspace&#39;s members, campaigns, package negotiation status, and the parent Agency&#39;s AI credit usage.</li><li><strong>Interface:</strong> Workspace dashboard screen at <code>/workspaces/:id/dashboard</code>, showing summary cards.</li><li><strong>Data Processing:</strong> The system resolves the Workspace, confirms the caller is an active member, then aggregates: active member count and role breakdown (<code>WorkspaceMemberRepository.findByWorkspaceIdAndIsActiveTrue</code>, grouped by role); campaign count and status breakdown (via <code>WorkspaceMediaPackageRepository.findByWorkspaceId</code> → <code>MediaCampaignRepository.findByWorkspaceMediaPackageId</code>, grouped by <code>CampaignStatus</code>); the current package negotiation status (<code>WorkspaceMediaPackage.negotiationStatus</code>, <code>null</code> if the Workspace has no package yet); and the parent Agency&#39;s AI credit usage for the current calendar month (<code>AiCreditLedgerRepository.findByAgencyIdAndMonth</code>).</li><li><strong>Known scope note:</strong> No Task or Material entity exists in this codebase, so this dashboard does not (and cannot) show a Task summary — an earlier draft of this spec described one; that was aspirational, not grounded in code. AI credit usage is Agency-wide, not per-Workspace (<code>AiCreditLedger</code> has no <code>workspaceId</code> column) — the screen labels it explicitly as Agency-scoped rather than implying it is this Workspace&#39;s own usage.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Workspace Dashboard Screen:</p><ul><li>Header carrying the Workspace name (via <code>PageWrapper</code> title/description).</li><li>Four stat cards in a row: Active members, Total campaigns, Package status (or &quot;No package&quot; if none), Agency AI credits used this month (labeled with the month).</li><li>Two breakdown cards below: Members by role, Campaigns by status — each an empty list if the Workspace has no members/campaigns yet.</li><li>A newly created Workspace with no package/campaign shows member counts as normal, campaign count as 0, package status as &quot;No package&quot;.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> The Workspace identifier; the caller&#39;s authenticated identity.</li><li><strong>Input optional:</strong> None.</li><li><strong>System data:</strong> Active <code>WorkspaceMember</code> rows for the Workspace; the Workspace&#39;s <code>WorkspaceMediaPackage</code> (if any) and its <code>MediaCampaign</code> rows; the parent Agency&#39;s <code>AiCreditLedger</code> row for the current month.</li><li><strong>Output:</strong> The full Workspace profile (same shape as <code>GET /workspaces/{id}</code>), active member count and role breakdown, campaign count and status breakdown, package negotiation status (nullable), the Agency id, the current month string, and the Agency&#39;s AI credits used this month.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-29:</strong> Multi-tenancy — only members holding an active membership row in the Workspace (MANAGER, CREATOR, or CLIENT) may view its dashboard, enforced via both <code>@RequireRole</code> on the controller and <code>assertMember</code> in the service (same dual-layer pattern as <code>getWorkspace</code>, FR 3.4.13). There is no Workspace-level OWNER — OWNER exists only at Agency level.</li><li><strong>BR-03:</strong> The dashboard is read-only and changes no data.</li><li><strong>BR-04:</strong> An empty Workspace (no package, no campaigns) renders member counts normally and campaign/package fields as empty/zero/null rather than failing.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>Caller must be an active member of the Workspace; otherwise 403 <code>WORKSPACE_ACCESS_DENIED</code> (from <code>assertMember</code>) or 403 <code>FORBIDDEN</code> (from <code>@RequireRole</code> if the caller has no membership row at all — see FR 3.4.13 for the exact two-layer distinction).</li><li>Workspace must exist; otherwise 404 <code>WORKSPACE_NOT_FOUND</code>.</li><li>A Workspace with no package/campaigns must render without error (empty maps, <code>packageNegotiationStatus: null</code>, <code>totalCampaigns: 0</code>).</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>Member opens the Dashboard of a Workspace.</li><li>FE calls <code>GET /api/v1/workspaces/{workspaceId}/dashboard</code>.</li><li>System resolves the Workspace (<code>findWorkspaceOrThrow</code>) and confirms active membership (<code>assertMember</code>, BR-29).</li><li>System aggregates active member count/role breakdown, campaign count/status breakdown, package negotiation status, and the Agency&#39;s current-month AI credit usage.</li><li>Screen renders the stat cards and breakdown lists; an empty Workspace shows zeros/empty lists without error.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>3.a1: The Workspace does not exist → 404 <code>WORKSPACE_NOT_FOUND</code>, toast MSG38. 3.a2: The member returns to the Workspace list (3.4.10).</li><li>3.b1: Caller is not an active member of the Workspace (BR-29) → 403 <code>WORKSPACE_ACCESS_DENIED</code> or <code>FORBIDDEN</code>, toast MSG40. 3.b2: The member returns to the Workspace list (3.4.10).</li><li>4.a1: Workspace has no package yet → <code>packageNegotiationStatus</code> is <code>null</code>, <code>totalCampaigns</code> is 0 (BR-04). 4.a2: The member continues viewing the dashboard normally; the package/campaign cards show empty states.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>No data is changed; the Workspace&#39;s member, campaign, package, and Agency AI credit summary is displayed.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Time-series charts of activity over time (possible later extension).</li><li>Per-Workspace AI credit tracking (the underlying <code>AiCreditLedger</code> schema is Agency-scoped only; would need a schema change to break down by Workspace).</li><li>Task/Material summary (no such entity exists in this codebase).</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p><a href="./../../../BA/01-organization-structure.html">01-organization-structure.md</a>, <a href="./../../../BA/03-agency-workspace-management.html">03-agency-workspace-management.md</a></p>',27)])])}const m=a(s,[["render",i]]);export{u as __pageData,m as default};
